<?php
declare(strict_types=1);
if(!defined('CWP_BOOT')){http_response_code(404);exit;}
require_once CWP_CODE_ROOT.'/app/providers/domain_contracts.php';
function domain_contracts_render(array $p):void {
    $labels=['not_observed'=>'No renewal date has been saved for this assignment.','assignment_changed'=>'The studio needs to refresh the date for this assignment.','observed'=>'Latest saved observation','stale'=>'The saved observation is older than 15 minutes. Ask the studio to refresh it.','unfinished'=>'The latest date refresh has not completed.','unavailable'=>'The latest renewal date is unavailable.','access_changed'=>'The assignment or account changed during the latest refresh.','credential'=>'The studio needs to review the account connection.','refused'=>'The latest date refresh could not be completed.'];
    echo '<div data-domain-date><h3 style="overflow-wrap:anywhere">'.esc($p['domain']??'Registered domain').'</h3><p>'.esc($labels[$p['status']]??'The saved date needs review.').'</p>';
    if($p['date']!==null)echo '<p><strong>Provider renewal date: '.esc($p['date']).'</strong><br><span class="hint">Observed '.esc(gmdate('Y-m-d H:i:s',$p['observed_epoch'])).' UTC</span></p>';
    echo '<p class="hint">A saved provider date does not confirm expiry, a price, or a completed renewal.</p>';
    if($p['history']){echo '<details><summary>Saved date history</summary><ul>';foreach($p['history'] as $r)echo '<li>'.esc(gmdate('Y-m-d H:i:s',$r['observed_epoch'])).' UTC — '.($r['date']!==null?'Observed renewal date '.esc($r['date']):esc($r['state']==='unfinished'?'Refresh unfinished':'Date unavailable')).'</li>';echo '</ul></details>';}
    echo '</div>';
}
function domain_contracts_admin_render():void {
    provider_settings_manager();echo '<section class="workspace-card" id="domain-contracts"><h2>Domain renewal dates</h2><p>Save a dated observation for an assigned registered domain. Clients can see their saved dates and request a renewal review separately.</p>';
    try{$ready=provider_inventory_ready()&&provider_registrar_ready()&&domain_contracts_ready();}catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p></section>';return;}
    if(!$ready){echo '<form method="post">';admin_action('provider_inventory_contract_prepare');admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn gold">Enable renewal dates</button></form><p class="hint">Prepare registered domains above first.</p></section>';return;}
    $page=max(1,min(10000,(int)($_GET['contract_page']??1)));$links=all('SELECT l.id,l.revision,c.name AS client_name FROM '.table('provider_registrar_links').' l JOIN '.table('studio_clients').' c ON c.id=l.client_id ORDER BY l.domain LIMIT 20 OFFSET '.(($page-1)*20));if(!$links)echo '<p>Assign a registered domain to a client first.</p>';
    foreach($links as $l){echo '<article class="workspace-card"><p>'.esc($l['client_name']).'</p>';try{[$b,$p]=staff_locked(fn()=>staff_transaction(fn()=>[domain_contracts_binding($l['id'],(int)$l['revision']),domain_contracts_project($l['id'],(int)$l['revision'])]));domain_contracts_render($p);echo '<form method="post">';admin_action('provider_inventory_contract_refresh');foreach(['link_id'=>$l['id'],'link_revision'=>$l['revision'],'profile_revision'=>$b->data['profile_revision'],'refresh_id'=>$b->data['source_refresh_id']] as $k=>$v)echo '<input type="hidden" name="'.esc($k).'" value="'.esc((string)$v).'">';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn outline">Refresh renewal date</button></form>';}
        catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p>';}echo '</article>';}
    echo '<nav class="button-row" aria-label="Renewal date pages">';if($page>1)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['contract_page'=>$page-1])).'#domain-contracts">Previous domains</a>';if(count($links)===20&&$page<10000)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['contract_page'=>$page+1])).'#domain-contracts">More domains</a>';echo '</nav></section>';
}
